// 'was/were' -> ['was', 'were']; 'born(e)' -> ['born', 'borne']
function verbFormCandidates(form) {
  if (form.includes('/')) return form.split('/').map((part) => part.trim())
  const optionalSuffix = form.match(/^(.+)\((.+)\)$/)
  if (optionalSuffix) return [optionalSuffix[1], optionalSuffix[1] + optionalSuffix[2]]
  return [form]
}

