export const VERBS = RAW_VERBS.map(
  (
    [
      base,
      pastSimple,
      pastParticiple,
      translation,
      example,
      examplePastSimple,
      examplePresentPerfect,
      common,
    ],
    index,
  ) => ({
    id: index,
    base,
    pastSimple,
    pastParticiple,
    translation,
    example,
    examplePastSimple,
    examplePresentPerfect,
    common,
    baseCandidates: verbFormCandidates(base),
    pastSimpleCandidates: verbFormCandidates(pastSimple),
    pastParticipleCandidates: verbFormCandidates(pastParticiple),
  }),
)

export const COMMON_VERBS = VERBS.filter((verb) => verb.common)
